entries[66098] = { ["name"] = "Plans: Obsidium Executioner", ["text"] = "Binds when picked up\nRequires Blacksmithing (425)\nUse: Teaches you how to make an Obsidium Executioner.\n\nObsidium Executioner\nBinds when equipped\nTwo-Hand Sword\n1,023 - 1,900 Damage Speed 3.50\n(417.57 damage per second)\n+229 Strength\n+343 Stamina\n+ 153 Mastery\nDurability 100 / 100\nRequires Level 81\nEquip: Improves critical strike rating by 153.\nSell Price:\nRequires Folded Obsidium (10), Elementium Bar (10), Volatile Earth (6)" }
entries[66099] = { ["name"] = "Plans: Obsidium Skeleton Key", ["text"] = "Binds when picked up\nRequires Blacksmithing (425)\nUse: Teaches you how to make an Obsidium Skeleton Key.\n\nObsidium Skeleton Key\nRequires Blacksmithing (475)\nUse: Allows opening of locks that require up to 525 lockpicking skill. The skeleton key is consumed in the process.\nSell Price:\nRequires Folded Obsidium (2)" }
entries[66100] = { ["name"] = "Plans: Ebonsteel Belt Buckle", ["text"] = "Binds when picked up\nRequires Blacksmithing (525)\nUse: Teaches you how to make an Ebonsteel Belt Buckle.\n\nEbonsteel Belt Buckle\nRequires Level 80\nUse: Permanently attach an ebonsteel belt buckle onto a belt, adding a socket to the belt.\n\nAttaching the belt buckle causes the item to become soulbound. Cannot be used on items level 500 or higher.\nSell Price:\nRequires Volatile Earth (4), Elementium Bar (4), Pyrium Bar (4)" }
entries[66101] = { ["name"] = "Plans: Pyrium Shield Spike", ["text"] = "Binds when picked up\nRequires Blacksmithing (525)\nUse: Teaches you how to make a Pyrium Shield Spike.\n\nPyrium Shield Spike\nBinds when equipped\nRequires Level 85\nUse: Attaches a Pyrium Spike to your shield that sometimes deals 210 to 350 damage when you block with it.\n\nAttaching a Pyrium Spike to your shield causes it to become soulbound.\nRequires Pyrium Bar (5)" }
entries[66102] = { ["name"] = "Plans: Elementium Shield Spike", ["text"] = "Binds when picked up\nRequires Blacksmithing (425)\nUse: Teaches you how to make an Elementium Shield Spike.\n\nElementium Shield Spike\nRequires Level 80\nUse: Attaches an Elementium Spike to your shield that deals 90 to 133 damage each time you block with it.\n\nAttaching an Elementium Spike to your shield causes it to become soulbound.\nRequires Elementium Bar (15)" }
entries[66103] = { ["name"] = "Plans: Pyrium Weapon Chain", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to make a Pyrium Weapon Chain.\n\nPyrium Weapon Chain\nBinds when equipped\nRequires Level 81\nUse: Attaches a chain to your weapon, reducing the duration of Disarm effects by 60% and increasing your hit rating by 40. Does not stack with other similar effects.\n\nAttaching the weapon chain causes the weapon to become soulbound.\nRequires Pyrium Bar" }
